设计模式是解决常见软件设计问题的可复用方案，.NET 框架本身大量使用了设计模式。


## 工厂模式（Factory Pattern）

**简单工厂**：
```csharp
public static class NotificationFactory
{
    public static INotification Create(string type)
    {
        return type switch
        {
            "email" => new EmailNotification(),
            "sms" => new SmsNotification(),
            "push" => new PushNotification(),
            _ => throw new ArgumentException($"Unknown type: {type}")
        };
    }
}
```

**抽象工厂**：
```csharp
public interface INotificationFactory
{
    INotification Create();
    INotificationTemplate CreateTemplate();
}

public class EmailNotificationFactory : INotificationFactory
{
    public INotification Create() => new EmailNotification();
    public INotificationTemplate CreateTemplate() => new EmailTemplate();
}

public class SmsNotificationFactory : INotificationFactory
{
    public INotification Create() => new SmsNotification();
    public INotificationTemplate CreateTemplate() => new SmsTemplate();
}
```

**工厂方法**：
```csharp
public abstract class NotificationService
{
    protected abstract INotification CreateNotification();

    public async Task SendAsync(string message)
    {
        var notification = CreateNotification();
        await notification.SendAsync(message);
    }
}

public class EmailNotificationService : NotificationService
{
    protected override INotification CreateNotification() => new EmailNotification();
}
```

## 依赖注入（Dependency Injection）

DI 是控制反转的具体实现：
```csharp
// 注册
services.AddTransient<INotification, EmailNotification>();
services.AddScoped<IOrderService, OrderService>();
services.AddSingleton<ICacheService, RedisCacheService>();

// 注入
public class OrderService : IOrderService
{
    private readonly INotification _notification;
    private readonly ICacheService _cache;

    public OrderService(INotification notification, ICacheService cache)
    {
        _notification = notification;
        _cache = cache;
    }
}
```

**工厂注册**：
```csharp
services.AddTransient<INotification>(provider =>
{
    var config = provider.GetRequiredService<IConfiguration>();
    var type = config["Notification:Type"];
    return type switch
    {
        "email" => new EmailNotification(),
        "sms" => new SmsNotification(),
        _ => throw new ArgumentException()
    };
});
```


## 装饰器模式（Decorator Pattern）

动态添加功能：
```csharp
public interface ICacheService
{
    Task<T> GetAsync<T>(string key);
    Task SetAsync<T>(string key, T value, TimeSpan? expiry = null);
}

public class RedisCacheService : ICacheService
{
    public async Task<T> GetAsync<T>(string key)
    {
        // Redis 实现
    }
}

public class LoggingCacheDecorator : ICacheService
{
    private readonly ICacheService _inner;
    private readonly ILogger _logger;

    public LoggingCacheDecorator(ICacheService inner, ILogger logger)
    {
        _inner = inner;
        _logger = logger;
    }

    public async Task<T> GetAsync<T>(string key)
    {
        _logger.LogInformation($"Getting cache key: {key}");
        var result = await _inner.GetAsync<T>(key);
        _logger.LogInformation($"Cache {(result != null ? "hit" : "miss")}: {key}");
        return result;
    }
}

public class CachingDecorator : ICacheService
{
    private readonly ICacheService _inner;
    private readonly IMemoryCache _memoryCache;

    public CachingDecorator(ICacheService inner, IMemoryCache memoryCache)
    {
        _inner = inner;
        _memoryCache = memoryCache;
    }

    public async Task<T> GetAsync<T>(string key)
    {
        if (_memoryCache.TryGetValue(key, out T cached))
            return cached;

        var result = await _inner.GetAsync<T>(key);
        if (result != null)
            _memoryCache.Set(key, result, TimeSpan.FromMinutes(5));

        return result;
    }
}

// 注册装饰器链
services.AddSingleton<RedisCacheService>();
services.AddSingleton<ICacheService>(provider =>
{
    var inner = provider.GetRequiredService<RedisCacheService>();
    var logger = provider.GetRequiredService<ILogger<LoggingCacheDecorator>>();
    var memoryCache = provider.GetRequiredService<IMemoryCache>();

    return new CachingDecorator(
        new LoggingCacheDecorator(inner, logger),
        memoryCache);
});
```


## 观察者模式（Observer Pattern）

事件驱动：
```csharp
// .NET 事件
public class OrderService
{
    public event EventHandler<OrderCreatedEventArgs> OrderCreated;

    public void CreateOrder(Order order)
    {
        // 创建订单逻辑
        OrderCreated?.Invoke(this, new OrderCreatedEventArgs(order));
    }
}

// 使用
var orderService = new OrderService();
orderService.OrderCreated += (sender, args) =>
{
    Console.WriteLine($"订单创建: {args.Order.Id}");
};
```

**IObservable<T>**：
```csharp
public class StockPriceProvider : IObservable<decimal>
{
    private readonly List<IObserver<decimal>> _observers = new();

    public IDisposable Subscribe(IObserver<decimal> observer)
    {
        _observers.Add(observer);
        return new Unsubscriber(_observers, observer);
    }

    public void UpdatePrice(decimal price)
    {
        foreach (var observer in _observers)
        {
            observer.OnNext(price);
        }
    }
}
```

## 中间件模式（Middleware Pattern）

请求管道：
```csharp
public class RequestLoggingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;

    public RequestLoggingMiddleware(RequestDelegate next, ILogger logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        _logger.LogInformation($"Request: {context.Request.Path}");
        await _next(context);
        _logger.LogInformation($"Response: {context.Response.StatusCode}");
    }
}

// 注册
app.UseMiddleware<RequestLoggingMiddleware>();
```


## 策略模式（Strategy Pattern）

算法可替换：
```csharp
public interface IPricingStrategy
{
    decimal CalculatePrice(Order order);
}

public class RegularPricing : IPricingStrategy
{
    public decimal CalculatePrice(Order order) => order.TotalAmount;
}

public class DiscountPricing : IPricingStrategy
{
    public decimal CalculatePrice(Order order) => order.TotalAmount * 0.9m;
}

public class OrderService
{
    private readonly IPricingStrategy _pricingStrategy;

    public OrderService(IPricingStrategy pricingStrategy)
    {
        _pricingStrategy = pricingStrategy;
    }

    public decimal GetPrice(Order order)
    {
        return _pricingStrategy.CalculatePrice(order);
    }
}
```


## 仓储模式（Repository Pattern）

数据访问抽象：
```csharp
public interface IRepository<T> where T : class
{
    Task<T> GetByIdAsync(int id);
    Task<IEnumerable<T>> GetAllAsync();
    Task AddAsync(T entity);
    void Update(T entity);
    void Delete(T entity);
}

public class Repository<T> : IRepository<T> where T : class
{
    protected readonly DbContext _context;
    protected readonly DbSet<T> _dbSet;

    public Repository(DbContext context)
    {
        _context = context;
        _dbSet = context.Set<T>();
    }

    // 实现接口方法
}
```


## 单例模式（Singleton Pattern）

```csharp
public sealed class Singleton
{
    private static readonly Lazy<Singleton> _instance = new(() => new Singleton());

    public static Singleton Instance => _instance.Value;

    private Singleton() { }
}

// 或使用 DI
services.AddSingleton<IMyService, MyService>();
```


## 命令模式（Command Pattern）

```csharp
public interface ICommand
{
    Task ExecuteAsync();
    Task UndoAsync();
}

public class CreateOrderCommand : ICommand
{
    private readonly Order _order;
    private readonly IOrderRepository _repository;

    public async Task ExecuteAsync() => await _repository.AddAsync(_order);
    public async Task UndoAsync() => await _repository.DeleteAsync(_order.Id);
}

public class CommandManager
{
    private readonly Stack<ICommand> _history = new();

    public async Task ExecuteAsync(ICommand command)
    {
        await command.ExecuteAsync();
        _history.Push(command);
    }

    public async Task UndoAsync()
    {
        if (_history.Count > 0)
        {
            var command = _history.Pop();
            await command.UndoAsync();
        }
    }
}
```


## 实际应用

**ASP.NET Core 中的模式**：
- 中间件模式：请求管道
- 依赖注入：服务注册
- 工厂模式：IServiceProvider
- 装饰器模式：HttpClient 中间件
- 观察者模式：IHostApplicationLifetime

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;

namespace DesignPatternsDemo
{
    // 工厂模式
    public interface INotification
    {
        Task SendAsync(string to, string message);
    }

    public class EmailNotification : INotification
    {
        public Task SendAsync(string to, string message)
        {
            Console.WriteLine($"Sending email to {to}: {message}");
            return Task.CompletedTask;
        }
    }

    public class SmsNotification : INotification
    {
        public Task SendAsync(string to, string message)
        {
            Console.WriteLine($"Sending SMS to {to}: {message}");
            return Task.CompletedTask;
        }
    }

    public interface INotificationFactory
    {
        INotification Create();
    }

    public class EmailNotificationFactory : INotificationFactory
    {
        public INotification Create() => new EmailNotification();
    }

    public class SmsNotificationFactory : INotificationFactory
    {
        public INotification Create() => new SmsNotification();
    }

    // 依赖注入 + 工厂
    public class NotificationService
    {
        private readonly INotificationFactory _factory;

        public NotificationService(INotificationFactory factory)
        {
            _factory = factory;
        }

        public async Task NotifyAsync(string to, string message)
        {
            var notification = _factory.Create();
            await notification.SendAsync(to, message);
        }
    }

    // 装饰器模式
    public interface ICacheService
    {
        Task<T> GetAsync<T>(string key);
        Task SetAsync<T>(string key, T value, TimeSpan? expiry = null);
    }

    public class InMemoryCacheService : ICacheService
    {
        private readonly Dictionary<string, (object Value, DateTime Expiry)> _cache = new();

        public Task<T> GetAsync<T>(string key)
        {
            if (_cache.TryGetValue(key, out var entry) && entry.Expiry > DateTime.UtcNow)
            {
                return Task.FromResult((T)entry.Value);
            }
            return Task.FromResult(default(T));
        }

        public Task SetAsync<T>(string key, T value, TimeSpan? expiry = null)
        {
            _cache[key] = (value, DateTime.UtcNow.Add(expiry ?? TimeSpan.FromMinutes(5)));
            return Task.CompletedTask;
        }
    }

    public class LoggingCacheDecorator : ICacheService
    {
        private readonly ICacheService _inner;

        public LoggingCacheDecorator(ICacheService inner)
        {
            _inner = inner;
        }

        public async Task<T> GetAsync<T>(string key)
        {
            Console.WriteLine($"[LOG] Getting cache: {key}");
            var result = await _inner.GetAsync<T>(key);
            Console.WriteLine($"[LOG] Cache {(result != null ? "hit" : "miss")}: {key}");
            return result;
        }

        public async Task SetAsync<T>(string key, T value, TimeSpan? expiry = null)
        {
            Console.WriteLine($"[LOG] Setting cache: {key}");
            await _inner.SetAsync(key, value, expiry);
        }
    }

    public class MetricsCacheDecorator : ICacheService
    {
        private readonly ICacheService _inner;
        private int _hits;
        private int _misses;

        public MetricsCacheDecorator(ICacheService inner)
        {
            _inner = inner;
        }

        public async Task<T> GetAsync<T>(string key)
        {
            var result = await _inner.GetAsync<T>(key);
            if (result != null) _hits++;
            else _misses++;
            return result;
        }

        public Task SetAsync<T>(string key, T value, TimeSpan? expiry = null)
        {
            return _inner.SetAsync(key, value, expiry);
        }

        public double HitRate => _hits + _misses > 0 ? (double)_hits / (_hits + _misses) : 0;
    }

    // 观察者模式
    public class EventBus
    {
        private readonly Dictionary<Type, List<Delegate>> _handlers = new();

        public void Subscribe<T>(Action<T> handler)
        {
            var type = typeof(T);
            if (!_handlers.ContainsKey(type))
                _handlers[type] = new List<Delegate>();
            _handlers[type].Add(handler);
        }

        public void Publish<T>(T @event)
        {
            var type = typeof(T);
            if (_handlers.TryGetValue(type, out var handlers))
            {
                foreach (var handler in handlers)
                {
                    handler.DynamicInvoke(@event);
                }
            }
        }
    }

    // 策略模式
    public interface IDiscountStrategy
    {
        decimal CalculateDiscount(decimal amount);
    }

    public class NoDiscount : IDiscountStrategy
    {
        public decimal CalculateDiscount(decimal amount) => 0;
    }

    public class PercentageDiscount : IDiscountStrategy
    {
        private readonly decimal _percentage;

        public PercentageDiscount(decimal percentage)
        {
            _percentage = percentage;
        }

        public decimal CalculateDiscount(decimal amount) => amount * _percentage / 100;
    }

    public class FixedDiscount : IDiscountStrategy
    {
        private readonly decimal _amount;

        public FixedDiscount(decimal amount)
        {
            _amount = amount;
        }

        public decimal CalculateDiscount(decimal amount) => Math.Min(_amount, amount);
    }

    public class PricingService
    {
        private readonly IDiscountStrategy _discountStrategy;

        public PricingService(IDiscountStrategy discountStrategy)
        {
            _discountStrategy = discountStrategy;
        }

        public decimal CalculateFinalPrice(decimal originalPrice)
        {
            var discount = _discountStrategy.CalculateDiscount(originalPrice);
            return originalPrice - discount;
        }
    }

    // 配置服务
    public static class DesignPatternServiceExtensions
    {
        public static IServiceCollection AddDesignPatterns(this IServiceCollection services)
        {
            // 工厂模式
            services.AddSingleton<INotificationFactory, EmailNotificationFactory>();
            services.AddScoped<NotificationService>();

            // 装饰器模式
            services.AddSingleton<InMemoryCacheService>();
            services.AddSingleton<ICacheService>(provider =>
            {
                var inner = provider.GetRequiredService<InMemoryCacheService>();
                return new MetricsCacheDecorator(new LoggingCacheDecorator(inner));
            });

            // 观察者模式
            services.AddSingleton<EventBus>();

            // 策略模式
            services.AddSingleton<IDiscountStrategy>(new PercentageDiscount(10));
            services.AddScoped<PricingService>();

            return services;
        }
    }
}
